// app.js — Phase 3: Money practice mode (separate from vocabulary), a Numbers
// vocab category, and every setting saved to localStorage and restored on load.
// Card content comes from seed-cards.json; money/number cards are generated by
// js/es-numbers.js; language/UI text comes from config.js.

const screens = {
  menu: document.getElementById('menu-screen'),
  options: document.getElementById('options-screen'),
  manageCards: document.getElementById('manage-cards-screen'),
  cardForm: document.getElementById('card-form-screen'),
  session: document.getElementById('session-screen'),
  summary: document.getElementById('summary-screen')
};

function showScreen(name) {
  Object.values(screens).forEach(s => s.classList.remove('active'));
  screens[name].classList.add('active');
  if (name === 'menu') {
    renderMenuStats();
    renderBackupReminder();
  }
}

// ---- Settings: load, save, defaults ----
function loadSettings() {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(SETTINGS_STORAGE_KEY)) || {};
  } catch (e) {
    saved = {};
  }
  return {
    direction: saved.direction || DEFAULT_SETTINGS.direction,
    categories: Object.assign({}, DEFAULT_SETTINGS.categories, saved.categories),
    moneyKind: saved.moneyKind || DEFAULT_SETTINGS.moneyKind,
    moneyMax: saved.moneyMax || DEFAULT_SETTINGS.moneyMax,
    sessionLength: saved.sessionLength || DEFAULT_SETTINGS.sessionLength,
    showTimer: typeof saved.showTimer === 'boolean' ? saved.showTimer : DEFAULT_SETTINGS.showTimer,
    autoPlay: typeof saved.autoPlay === 'boolean' ? saved.autoPlay : DEFAULT_SETTINGS.autoPlay,
    slowSpeed: typeof saved.slowSpeed === 'boolean' ? saved.slowSpeed : DEFAULT_SETTINGS.slowSpeed,
    voiceName: typeof saved.voiceName === 'string' ? saved.voiceName : DEFAULT_SETTINGS.voiceName,
    voicePracticeEnabled: typeof saved.voicePracticeEnabled === 'boolean' ? saved.voicePracticeEnabled : DEFAULT_SETTINGS.voicePracticeEnabled,
    voiceStrictness: saved.voiceStrictness || DEFAULT_SETTINGS.voiceStrictness,
    theme: saved.theme === 'light' ? 'light' : DEFAULT_SETTINGS.theme
  };
}

function saveSettings() {
  localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(settings));
}

let settings = loadSettings();

// Applies the current theme to the page and keeps the status-bar color
// (meta theme-color) in sync; manifest.json's own theme/background colors
// stay fixed on dark since a static manifest can't react to this setting.
function applyTheme() {
  document.documentElement.setAttribute('data-theme', settings.theme);
  const themeColorMeta = document.querySelector('meta[name="theme-color"]');
  if (themeColorMeta) themeColorMeta.setAttribute('content', settings.theme === 'light' ? '#f4f6f8' : '#1b4f72');
}
applyTheme();

// ---- Lifetime practice-time stats ----
function loadStats() {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(STATS_STORAGE_KEY)) || {};
  } catch (e) {
    saved = {};
  }
  return {
    totalPracticeMs: typeof saved.totalPracticeMs === 'number' ? saved.totalPracticeMs : 0,
    lastPracticeDate: typeof saved.lastPracticeDate === 'string' ? saved.lastPracticeDate : null,
    currentStreak: typeof saved.currentStreak === 'number' ? saved.currentStreak : 0
  };
}

function saveStats() {
  localStorage.setItem(STATS_STORAGE_KEY, JSON.stringify(stats));
}

let stats = loadStats();

// ---- Card data: Carl's edits/deletes/custom cards ----
// Kept separate from seed-cards.json so a future update to the shipped
// deck merges in rather than silently overwriting Carl's own changes.
function loadCardData() {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(CUSTOM_CARDS_STORAGE_KEY)) || {};
  } catch (e) {
    saved = {};
  }
  return {
    overrides: saved.overrides && typeof saved.overrides === 'object' ? saved.overrides : {},
    customCards: Array.isArray(saved.customCards) ? saved.customCards : [],
    lastExportAt: typeof saved.lastExportAt === 'number' ? saved.lastExportAt : null
  };
}

function saveCardData() {
  localStorage.setItem(CUSTOM_CARDS_STORAGE_KEY, JSON.stringify(cardData));
}

let cardData = loadCardData();

