// ---- Text-to-speech ----
let spanishVoices = [];

function loadVoices() {
  const voices = ('speechSynthesis' in window) ? speechSynthesis.getVoices() : [];
  spanishVoices = voices.filter(v => v.lang && v.lang.toLowerCase().startsWith('es'));

  voicePicker.innerHTML = '';
  spanishVoices.forEach(function (voice) {
    const option = document.createElement('option');
    option.value = voice.name;
    option.textContent = voice.name + ' (' + voice.lang + ')';
    voicePicker.appendChild(option);
  });
  voicePickerRow.style.display = spanishVoices.length > 1 ? 'flex' : 'none';
  if (spanishVoices.some(v => v.name === settings.voiceName)) {
    voicePicker.value = settings.voiceName;
  }
}

if ('speechSynthesis' in window) {
  loadVoices();
  speechSynthesis.addEventListener('voiceschanged', loadVoices);
}

function speakSpanish(text) {
  if (!('speechSynthesis' in window) || !text) return;
  speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = 'es-MX';
  utterance.rate = settings.slowSpeed ? 0.7 : 1.0;
  const chosenVoice = spanishVoices.find(v => v.name === settings.voiceName);
  if (chosenVoice) utterance.voice = chosenVoice;
  speechSynthesis.speak(utterance);
}

// ---- Deck loading ----
let allCards = [];
let seedCardsRaw = [];

// Merges the shipped seed deck with Carl's own overrides (edits/deletes) and
// custom cards. Re-run after any Manage Cards change or import so a future
// seed-cards.json update (new built-in cards) only ever adds, never undoes
// something Carl changed.
function rebuildAllCards() {
  allCards = seedCardsRaw
    .filter(function (c) { return !(cardData.overrides[c.id] && cardData.overrides[c.id].deleted); })
    .map(function (c) { return Object.assign({}, c, cardData.overrides[c.id] || {}); })
    .concat(cardData.customCards);
}

fetch('./seed-cards.json')
  .then(res => res.json())
  .then(data => {
    seedCardsRaw = data.cards;
    rebuildAllCards();
  })
  .catch(err => {
    console.error(err);
    alert(STRINGS.loadError);
  });

// ---- Manage Cards screen ----
let manageCardsFilter = 'words';
let editingCardId = null; // null means the form is adding a new card

const cardListEl = document.getElementById('card-list');
const formCategorySelect = document.getElementById('form-category');
const formSiNoRow = document.getElementById('form-si-no-row');

function updateFilterButtonStyles() {
  MANAGEABLE_CATEGORIES.forEach(function (cat) {
    document.getElementById('filter-' + cat).classList.toggle('active-filter', cat === manageCardsFilter);
  });
}

function renderManageCardsList() {
  cardListEl.innerHTML = '';
  allCards.filter(function (c) { return c.category === manageCardsFilter; }).forEach(function (card) {
    const row = document.createElement('div');
    row.className = 'card-row';

    const enabledCheckbox = document.createElement('input');
    enabledCheckbox.type = 'checkbox';
    enabledCheckbox.checked = card.isEnabled;
    enabledCheckbox.addEventListener('change', function () {
      setCardFields(card.id, { isEnabled: enabledCheckbox.checked });
    });

    const textWrap = document.createElement('div');
    textWrap.className = 'card-row-text';
    const spanishLine = document.createElement('div');
    spanishLine.className = 'card-row-spanish';
    spanishLine.textContent = card.spanish;
    const englishLine = document.createElement('div');
    englishLine.className = 'card-row-english';
    englishLine.textContent = card.english;
    textWrap.appendChild(spanishLine);
    textWrap.appendChild(englishLine);

    if (card.timesSeen > 0) {
      const statsLine = document.createElement('div');
      statsLine.className = 'card-row-stats';
      const pct = Math.round(100 * card.timesCorrect / card.timesSeen);
      statsLine.textContent = STRINGS.cardStatsLabel
        .replace('{pct}', pct).replace('{correct}', card.timesCorrect).replace('{seen}', card.timesSeen);
      textWrap.appendChild(statsLine);
    }

    const editBtn = document.createElement('button');
    editBtn.type = 'button';
    editBtn.textContent = STRINGS.editCardButton;
    editBtn.addEventListener('click', function () { openCardForm(card); });

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.textContent = STRINGS.deleteCardButton;
    deleteBtn.addEventListener('click', function () { deleteCard(card); });

    row.appendChild(enabledCheckbox);
    row.appendChild(textWrap);
    row.appendChild(editBtn);
    row.appendChild(deleteBtn);
    cardListEl.appendChild(row);
  });
}

// Writes fields to a built-in card's override entry, or directly onto a
// custom card — either way, re-merges and re-renders so the change is
// reflected immediately.
function setCardFields(cardId, fields) {
  const card = allCards.find(function (c) { return c.id === cardId; });
  if (!card) return;
  if (card.isBuiltIn) {
    cardData.overrides[cardId] = Object.assign({}, cardData.overrides[cardId], fields);
  } else {
    const idx = cardData.customCards.findIndex(function (c) { return c.id === cardId; });
    if (idx !== -1) cardData.customCards[idx] = Object.assign({}, cardData.customCards[idx], fields);
  }
  saveCardData();
  rebuildAllCards();
  renderManageCardsList();
}

function deleteCard(card) {
  if (!confirm(STRINGS.deleteCardConfirm.replace('{card}', card.spanish))) return;
  if (card.isBuiltIn) {
    cardData.overrides[card.id] = Object.assign({}, cardData.overrides[card.id], { deleted: true });
  } else {
    cardData.customCards = cardData.customCards.filter(function (c) { return c.id !== card.id; });
  }
  saveCardData();
  rebuildAllCards();
  renderManageCardsList();
}

MANAGEABLE_CATEGORIES.forEach(function (cat) {
  document.getElementById('filter-' + cat).addEventListener('click', function () {
    manageCardsFilter = cat;
    updateFilterButtonStyles();
    renderManageCardsList();
  });
});

document.getElementById('manage-cards-btn').addEventListener('click', function () {
  updateFilterButtonStyles();
  renderManageCardsList();
  showScreen('manageCards');
});
document.getElementById('manage-cards-back-btn').addEventListener('click', () => showScreen('options'));

// ---- Add / Edit card form ----
function updateFormSiNoVisibility() {
  formSiNoRow.style.display = formCategorySelect.value === 'questions' ? 'flex' : 'none';
}
formCategorySelect.addEventListener('change', updateFormSiNoVisibility);

function openCardForm(card) {
  editingCardId = card ? card.id : null;
  document.getElementById('card-form-heading').textContent = card ? STRINGS.editCardHeading : STRINGS.addCardHeading;
  formCategorySelect.value = card ? card.category : manageCardsFilter;
  document.getElementById('form-spanish').value = card ? card.spanish : '';
  document.getElementById('form-english').value = card ? card.english : '';
  document.getElementById('form-acceptable').value = card && card.acceptableAnswers ? card.acceptableAnswers.join('\n') : '';
  document.getElementById('form-si').value = card && card.siAnswer ? card.siAnswer : '';
  document.getElementById('form-no').value = card && card.noAnswer ? card.noAnswer : '';
  updateFormSiNoVisibility();
  showScreen('cardForm');
}

document.getElementById('add-card-btn').addEventListener('click', () => openCardForm(null));
document.getElementById('card-form-back-btn').addEventListener('click', () => showScreen('manageCards'));

document.getElementById('form-save-btn').addEventListener('click', function () {
  const category = formCategorySelect.value;
  const spanish = document.getElementById('form-spanish').value.trim();
  const english = document.getElementById('form-english').value.trim();
  if (!spanish || !english) {
    alert(STRINGS.cardFormValidation);
    return;
  }
  const acceptableAnswers = document.getElementById('form-acceptable').value
    .split('\n').map(function (s) { return s.trim(); }).filter(Boolean);
  const fields = { category: category, spanish: spanish, english: english, acceptableAnswers: acceptableAnswers };
  if (category === 'questions') {
    fields.siAnswer = document.getElementById('form-si').value.trim();
    fields.noAnswer = document.getElementById('form-no').value.trim();
  }

  if (editingCardId) {
    setCardFields(editingCardId, fields);
  } else {
    cardData.customCards.push(Object.assign({
      id: 'custom-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
      notes: '', pronunciationHint: '', isBuiltIn: false, isEnabled: true, timesSeen: 0, timesCorrect: 0
    }, fields));
    saveCardData();
    rebuildAllCards();
  }

  manageCardsFilter = category;
  updateFilterButtonStyles();
  renderManageCardsList();
  showScreen('manageCards');
});

// ---- Export / Import backup ----
document.getElementById('export-btn').addEventListener('click', function () {
  cardData.lastExportAt = Date.now();
  saveCardData();

  const payload = { exportedAt: cardData.lastExportAt, settings: settings, stats: stats, cardData: cardData };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'espanol-en-el-taller-backup.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  renderBackupReminder();
});

const importFileInput = document.getElementById('import-file-input');
document.getElementById('import-btn').addEventListener('click', () => importFileInput.click());

importFileInput.addEventListener('change', function (e) {
  const file = e.target.files[0];
  e.target.value = ''; // reset so the same file can be reselected later
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function () {
    let payload;
    try {
      payload = JSON.parse(reader.result);
    } catch (err) {
      alert(STRINGS.importError);
      return;
    }
    if (!payload || !payload.cardData) {
      alert(STRINGS.importError);
      return;
    }
    if (!confirm(STRINGS.importConfirm)) return;

    localStorage.setItem(CUSTOM_CARDS_STORAGE_KEY, JSON.stringify(payload.cardData));
    if (payload.settings) localStorage.setItem(SETTINGS_STORAGE_KEY, JSON.stringify(payload.settings));
    if (payload.stats) localStorage.setItem(STATS_STORAGE_KEY, JSON.stringify(payload.stats));
    window.location.reload();
  };
  reader.readAsText(file);
});

// ---- Backup reminder (main menu) ----
let backupReminderDismissed = false;
const backupReminderLine = document.getElementById('backup-reminder-line');

function shouldShowBackupReminder() {
  const hasCustomData = cardData.customCards.length > 0 || Object.keys(cardData.overrides).length > 0;
  if (!hasCustomData) return false;
  if (!cardData.lastExportAt) return true;
  const daysSince = (Date.now() - cardData.lastExportAt) / (1000 * 60 * 60 * 24);
  return daysSince >= BACKUP_REMINDER_DAYS;
}

function renderBackupReminder() {
  backupReminderLine.style.display = (!backupReminderDismissed && shouldShowBackupReminder()) ? 'flex' : 'none';
}

document.getElementById('backup-reminder-dismiss').addEventListener('click', function () {
  backupReminderDismissed = true;
  backupReminderLine.style.display = 'none';
});

// ---- Shuffle helper ----
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// ---- Session state ----
let session = null; // { queue, index, correct }
let sessionInterval = null;
let lastBuilder = buildSession; // which builder "Play again" should reuse; declared below

// ---- Pause-aware active clock ----
// Tracks only foregrounded time for the current session (backgrounding the
// app shouldn't count), and folds elapsed time into the lifetime total as
// it goes so a backgrounded tab getting killed by iOS doesn't lose it.
let activeSegmentStart = null; // timestamp the current active segment began, or null if paused/no session
let sessionActiveMs = 0; // accumulated active ms from closed segments this session

function sessionElapsedMs() {
  return sessionActiveMs + (activeSegmentStart !== null ? Date.now() - activeSegmentStart : 0);
}

// Commits elapsed time from the open segment into both the session total
// and the persisted lifetime total, then immediately reopens the segment.
function flushActiveClock() {
  if (activeSegmentStart === null) return;
  const now = Date.now();
  const delta = now - activeSegmentStart;
  sessionActiveMs += delta;
  stats.totalPracticeMs += delta;
  saveStats();
  activeSegmentStart = now;
}

function pauseActiveClock() {
  flushActiveClock();
  activeSegmentStart = null;
}

function resumeActiveClock() {
  if (activeSegmentStart === null) activeSegmentStart = Date.now();
}

document.addEventListener('visibilitychange', function () {
  if (!session) return;
  if (document.hidden) pauseActiveClock();
  else resumeActiveClock();
});

window.addEventListener('pagehide', function () {
  if (!session) return;
  pauseActiveClock();
});

function enabledCategories() {
  return Object.keys(settings.categories).filter(cat => settings.categories[cat]);
}

// Resolves to an actual per-card direction; 'mixed' picks one at random for each card.
function pickDirection() {
  if (settings.direction === 'mixed') {
    return Math.random() < 0.5 ? 'esToEn' : 'enToEs';
  }
  return settings.direction;
}

// Vocabulary pool: seed cards (Words/Phrases/Common Questions) plus freshly
// generated Numbers cards, whichever categories are enabled.
function buildVocabPool() {
  const cats = enabledCategories();
  let pool = allCards.filter(c => c.isEnabled && cats.includes(c.category));
  if (cats.includes('numbers')) {
    pool = pool.concat(generateNumberCardPool(30));
  }
  return pool;
}

// Shuffles `pool` into a queue of exactly `length` entries, reshuffling and
// looping back through the pool if it's smaller than `length` — shared by
// every vocab-style session builder below.
function buildShuffledQueue(pool, length) {
  const queue = [];
  let shuffled = shuffle(pool.slice());
  let i = 0;
  while (queue.length < length) {
    if (i >= shuffled.length) {
      shuffled = shuffle(pool.slice());
      i = 0;
    }
    queue.push({ card: shuffled[i], direction: pickDirection() });
    i++;
  }
  return queue;
}

function buildSession() {
  const pool = buildVocabPool();
  if (pool.length === 0) {
    alert(STRINGS.noCardsEnabled);
    return null;
  }
  return { queue: buildShuffledQueue(pool, settings.sessionLength), index: 0, correct: 0 };
}

// Weakest cards: ranks currently-enabled, manageable cards by accuracy
// (lowest first) and practices only the worst of them. Money/Numbers are
// generated fresh each session and have no stable per-card accuracy, so
// they're excluded the same way Manage Cards already excludes them.
function buildWeakestSession() {
  const cats = enabledCategories();
  const pool = allCards.filter(function (c) {
    return c.isEnabled && MANAGEABLE_CATEGORIES.includes(c.category) &&
      cats.includes(c.category) && c.timesSeen >= WEAKEST_MIN_SEEN;
  });
  if (pool.length === 0) {
    alert(STRINGS.notEnoughWeakestData);
    return null;
  }
  pool.sort(function (a, b) { return (a.timesCorrect / a.timesSeen) - (b.timesCorrect / b.timesSeen); });
  const weakest = pool.slice(0, Math.min(settings.sessionLength, pool.length));
  return { queue: buildShuffledQueue(weakest, settings.sessionLength), index: 0, correct: 0 };
}

// Money session: cards are generated fresh each time, never stored.
function buildMoneySession() {
  const queue = [];
  for (let i = 0; i < settings.sessionLength; i++) {
    queue.push({ card: generateMoneyCard(settings.moneyKind, settings.moneyMax), direction: pickDirection() });
  }

  return {
    queue,
    index: 0,
    correct: 0
  };
}

// ---- Rendering a card ----
const cardInner = document.getElementById('card-inner');
const cardFront = document.getElementById('card-front');
const cardBack = document.getElementById('card-back');
const gradingRow = document.getElementById('grading-row');
const nextRow = document.getElementById('next-row');
const peekRow = document.getElementById('peek-row');
const peekBtn = document.getElementById('peek-btn');
const speakBtn = document.getElementById('speak-btn');
const micBtn = document.getElementById('mic-btn');
const voiceFeedbackEl = document.getElementById('voice-feedback');
const progressText = document.getElementById('progress-text');
const timerText = document.getElementById('timer-text');

function addSubLine(container, text) {
  const line = document.createElement('div');
  line.className = 'card-sub';
  line.textContent = text;
  container.appendChild(line);
}

function renderCard() {
  const entry = session.queue[session.index];
  const card = entry.card;
  const direction = entry.direction;
  cardInner.classList.remove('flipped');
  gradingRow.style.display = 'none';
  nextRow.style.display = 'none';
  peekRow.style.display = 'none';

  cardFront.innerHTML = '';
  cardBack.innerHTML = '';

  voiceFeedbackEl.style.display = 'none';
  voiceFeedbackEl.innerHTML = '';
  micBtn.classList.remove('listening');
  micBtn.textContent = STRINGS.micButton;

  if (direction === 'enToEs') {
    cardFront.textContent = card.english;
    cardBack.textContent = card.spanish;
    // Spanish is on the back here — hide the speaker until the card is flipped,
    // so it can't be used to hear the answer before attempting it.
    speakBtn.style.display = 'none';
  } else {
    cardFront.textContent = card.spanish;
    cardBack.textContent = card.english;
    speakBtn.style.display = '';
  }

  // Voice practice works in either direction now — whichever side is
  // hidden is the thing being practiced, same reasoning as the speaker
  // button: only offer it pre-flip, before the answer is visible.
  micBtn.style.display = micAvailableThisSession() ? '' : 'none';

  if (card.category === 'questions') {
    addSubLine(cardBack, 'Sí: ' + card.siAnswer);
    addSubLine(cardBack, 'No: ' + card.noAnswer);
  }

  progressText.textContent = (session.index + 1) + ' / ' + session.queue.length;

  // Spanish is already showing on the front in this direction; speak it now.
  if (settings.autoPlay && direction !== 'enToEs') {
    speakSpanish(card.spanish);
  }
}

speakBtn.addEventListener('click', function () {
  speakSpanish(session.queue[session.index].card.spanish);
});

// Spanish just became visible on the back (manual flip or a voice-practice
// attempt); reveal the speaker — for practice and reinforcement even after
// a voice attempt — and, if auto-play is on, speak it now.
function revealSpeakerOnFlip(entry) {
  if (entry.direction === 'enToEs') {
    speakBtn.style.display = '';
    if (settings.autoPlay) speakSpanish(entry.card.spanish);
  }
}

cardInner.addEventListener('click', function () {
  if (!cardInner.classList.contains('flipped')) {
    cardInner.classList.add('flipped');
    gradingRow.style.display = 'flex';
    peekRow.style.display = 'flex';
    micBtn.style.display = 'none';
    stopRecognition();
    revealSpeakerOnFlip(session.queue[session.index]);
  }
});

// Hold the peek button to see the front again; release to go back to the back.
function peekAtFront() {
  cardInner.classList.remove('flipped');
}
function stopPeeking() {
  cardInner.classList.add('flipped');
}
peekBtn.addEventListener('mousedown', peekAtFront);
peekBtn.addEventListener('mouseup', stopPeeking);
peekBtn.addEventListener('mouseleave', stopPeeking);
peekBtn.addEventListener('touchstart', function (e) { e.preventDefault(); peekAtFront(); });
peekBtn.addEventListener('touchend', stopPeeking);
peekBtn.addEventListener('touchcancel', stopPeeking);

// ---- Voice practice (speech recognition) ----
const SpeechRecognitionCtor = window.SpeechRecognition || window.webkitSpeechRecognition;
const voiceRecognitionSupported = !!SpeechRecognitionCtor;

let recognizing = false;
let activeRecognition = null;
let micDisabledThisSession = false; // set on a permission denial; reset per session

// Whether voice practice can be offered at all right now (per-card direction
// is checked separately in renderCard).
function micAvailableThisSession() {
  return voiceRecognitionSupported && settings.voicePracticeEnabled && !micDisabledThisSession;
}

// What to recognize and score against for a given card — whichever side is
// hidden is the thing being practiced. Spanish keeps its own accent-folding/
// digit-to-words normalization and acceptable-alternates list; English (or
// any future non-Spanish language) uses a simpler generic normalizer, plus
// runtime variants for the few cards whose English text uses "a / b" or
// "word (clarifier)" shorthand.
function resolveVoiceTarget(entry) {
  const card = entry.card;
  if (entry.direction === 'enToEs') {
    return {
      lang: 'es-MX',
      normalizeFn: normalizeSpanish,
      answers: [card.spanish].concat(card.acceptableAnswers || [])
    };
  }
  return {
    lang: 'en-US',
    normalizeFn: normalizeGeneric,
    answers: englishAnswerVariants(card.english)
  };
}

function stopRecognition() {
  if (activeRecognition) {
    activeRecognition.abort();
    activeRecognition = null;
  }
  recognizing = false;
  micBtn.classList.remove('listening');
  micBtn.textContent = STRINGS.micButton;
}

function showVoiceMessage(text) {
  voiceFeedbackEl.innerHTML = '';
  const msg = document.createElement('div');
  msg.className = 'voice-message';
  msg.textContent = text;
  voiceFeedbackEl.appendChild(msg);
  voiceFeedbackEl.style.display = 'block';
}

function renderVoiceFeedback(transcript, bestAnswer, wordThreshold, normalizeFn) {
  voiceFeedbackEl.innerHTML = '';
  const heardLine = document.createElement('div');
  heardLine.className = 'heard-line';
  heardLine.appendChild(document.createTextNode(STRINGS.heardLabel));
  wordMatchHighlights(transcript, bestAnswer, wordThreshold, normalizeFn).forEach(function (w) {
    const span = document.createElement('span');
    span.className = 'heard-word' + (w.matched ? '' : ' mismatch');
    span.textContent = w.word;
    heardLine.appendChild(span);
  });
  voiceFeedbackEl.appendChild(heardLine);
  voiceFeedbackEl.style.display = 'block';
}

// A heard transcript auto-grades the card exactly like tapping Got it/Missed
// would — same as manual grading, there's no "undo" once it's graded.
function handleVoiceResult(entry, transcript, voiceTarget) {
  // Strictness controls how closely each individual word has to sound to
  // count as a match — it does NOT let you skip or swap out a word. Every
  // word in whichever acceptable answer matched best has to be heard; a
  // shorter valid phrasing (e.g. "carro" instead of "el carro") is handled
  // by it being its own entry in acceptableAnswers, not by partial credit.
  const wordThreshold = VOICE_MATCH_THRESHOLDS[settings.voiceStrictness] || VOICE_MATCH_THRESHOLDS.normal;
  const best = scoreAgainstAnswers(transcript, voiceTarget.answers, wordThreshold, voiceTarget.normalizeFn);
  const isCorrect = best.score >= 1;

  renderVoiceFeedback(transcript, best.answer, wordThreshold, voiceTarget.normalizeFn);

  if (!cardInner.classList.contains('flipped')) {
    cardInner.classList.add('flipped');
    gradingRow.style.display = 'flex';
    peekRow.style.display = 'flex';
    revealSpeakerOnFlip(entry);
  }
  micBtn.style.display = 'none';

  grade(isCorrect);
}

micBtn.addEventListener('click', function () {
  if (recognizing || !voiceRecognitionSupported) return;
  const entry = session.queue[session.index];
  const voiceTarget = resolveVoiceTarget(entry);
  const recognition = new SpeechRecognitionCtor();
  recognition.lang = voiceTarget.lang;
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;

  recognizing = true;
  activeRecognition = recognition;
  micBtn.classList.add('listening');
  micBtn.textContent = STRINGS.micListening;
  voiceFeedbackEl.style.display = 'none';
  voiceFeedbackEl.innerHTML = '';

  recognition.onresult = function (event) {
    const transcript = event.results[0][0].transcript;
    handleVoiceResult(entry, transcript, voiceTarget);
  };

  recognition.onerror = function (event) {
    if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
      micDisabledThisSession = true;
      micBtn.style.display = 'none';
      showVoiceMessage(STRINGS.micDenied);
    } else {
      showVoiceMessage(STRINGS.micNoSpeech);
    }
  };

  recognition.onend = function () {
    recognizing = false;
    activeRecognition = null;
    micBtn.classList.remove('listening');
    micBtn.textContent = STRINGS.micButton;
  };

  recognition.start();
});

// Persists a practice result onto the card itself — skipped for Money/
// Numbers cards, which are generated fresh each session and were already
// excluded from Manage Cards for the same reason. Reuses the Phase 7
// merge-storage mechanism (overrides for built-ins, direct mutation for
// custom cards) so it survives reloads and future seed-data updates.
function recordCardResult(card, isCorrect) {
  if (!card || !MANAGEABLE_CATEGORIES.includes(card.category)) return;
  card.timesSeen = (card.timesSeen || 0) + 1;
  if (isCorrect) card.timesCorrect = (card.timesCorrect || 0) + 1;
  if (card.isBuiltIn) {
    cardData.overrides[card.id] = Object.assign({}, cardData.overrides[card.id], {
      timesSeen: card.timesSeen, timesCorrect: card.timesCorrect
    });
  } else {
    const custom = cardData.customCards.find(function (c) { return c.id === card.id; });
    if (custom) { custom.timesSeen = card.timesSeen; custom.timesCorrect = card.timesCorrect; }
  }
  saveCardData();
}

function grade(isCorrect) {
  const entry = session.queue[session.index];
  if (isCorrect) session.correct++;
  recordCardResult(entry.card, isCorrect);
  gradingRow.style.display = 'none';
  nextRow.style.display = 'flex';
}

document.getElementById('gotit-btn').addEventListener('click', () => grade(true));
document.getElementById('missed-btn').addEventListener('click', () => grade(false));

document.getElementById('next-btn').addEventListener('click', function () {
  session.index++;
  if (session.index >= session.queue.length) {
    finishSession();
  } else {
    renderCard();
  }
});

function formatElapsed(ms) {
  const elapsedSeconds = Math.round(ms / 1000);
  const mins = Math.floor(elapsedSeconds / 60);
  const secs = elapsedSeconds % 60;
  return mins + ':' + String(secs).padStart(2, '0');
}

// Lifetime total, formatted coarser (hours/minutes) than a session's mm:ss.
function formatDuration(ms) {
  const totalMinutes = Math.floor(ms / 60000);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours > 0) return hours + 'h ' + minutes + 'm';
  if (minutes > 0) return minutes + 'm';
  return '< 1m';
}

function stopSessionInterval() {
  if (sessionInterval) {
    clearInterval(sessionInterval);
    sessionInterval = null;
  }
}

function finishSession(cardsDone) {
  stopSessionInterval();
  stopRecognition();
  pauseActiveClock();
  const done = typeof cardsDone === 'number' ? cardsDone : session.queue.length;
  const elapsed = formatElapsed(sessionElapsedMs());

  document.getElementById('summary-cards').textContent =
    'Cards done: ' + done;
  document.getElementById('summary-correct').textContent =
    'Correct: ' + session.correct + ' / ' + done;
  document.getElementById('summary-time').textContent =
    'Time: ' + elapsed;

  showScreen('summary');
}

function startSessionWithBuilder(builderFn) {
  const s = builderFn();
  if (!s) return;
  lastBuilder = builderFn;
  session = s;
  sessionActiveMs = 0;
  micDisabledThisSession = false;
  updateStreak();
  resumeActiveClock();
  showScreen('session');
  renderCard();

  timerText.style.display = settings.showTimer ? 'block' : 'none';
  if (settings.showTimer) timerText.textContent = '0:00';

  // Always ticks during a session (not just when the timer is shown) so the
  // lifetime total keeps saving every second, crash-safe.
  sessionInterval = setInterval(function () {
    flushActiveClock();
    if (settings.showTimer) {
      timerText.textContent = formatElapsed(sessionElapsedMs());
    }
  }, 1000);
}

// ---- Navigation ----
document.getElementById('play-btn').addEventListener('click', () => startSessionWithBuilder(buildSession));
document.getElementById('weakest-btn').addEventListener('click', () => startSessionWithBuilder(buildWeakestSession));
document.getElementById('money-btn').addEventListener('click', () => startSessionWithBuilder(buildMoneySession));
document.getElementById('play-again-btn').addEventListener('click', () => startSessionWithBuilder(lastBuilder));
document.getElementById('options-btn').addEventListener('click', function () {
  renderOptionsScreen();
  showScreen('options');
});
document.getElementById('options-back-btn').addEventListener('click', () => showScreen('menu'));
document.getElementById('end-session-btn').addEventListener('click', function () {
  const currentCardGraded = nextRow.style.display === 'flex';
  finishSession(session.index + (currentCardGraded ? 1 : 0));
});
document.getElementById('summary-menu-btn').addEventListener('click', () => showScreen('menu'));

// ---- Offline support + update notification ----
const updateBanner = document.getElementById('update-banner');
const updateReloadBtn = document.getElementById('update-reload-btn');

if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('./sw.js').then(function (registration) {
    registration.addEventListener('updatefound', function () {
      const newWorker = registration.installing;
      if (!newWorker) return;
      newWorker.addEventListener('statechange', function () {
        if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
          updateBanner.style.display = 'block';
        }
      });
    });
  }).catch(function (err) {
    console.error('Service worker registration failed:', err);
  });

  let reloadedForUpdate = false;
  navigator.serviceWorker.addEventListener('controllerchange', function () {
    if (reloadedForUpdate) return;
    reloadedForUpdate = true;
    window.location.reload();
  });

  updateReloadBtn.addEventListener('click', function () {
    navigator.serviceWorker.getRegistration().then(function (registration) {
      if (registration && registration.waiting) {
        registration.waiting.postMessage({ type: 'SKIP_WAITING' });
      }
    });
  });
}
